pub(crate) fn is_empty(&self, tx: &Tx<T>) -> bool {
    let block = unsafe { self.head.as_ref() };
    // The `index` might be out of the bounds of the current block (e.g. when the
    // receiver has consumed every value of the current block, but the sender has
    // not started to fill the next block yet). In this case, the block might have
    // a ready slot at the position `index % BLOCK_CAP` from a previously consumed
    // value, so we cannot rely on `has_value` and need to check the length instead.
    if block.is_at_index(block::start_index(self.index)) && block.has_value(self.index) {
        return false;
    }

    // It is possible that a block has no value "now" but the list is still not empty.
    // To be sure, it is necessary to check the length of the list.
    self.len(tx) == 0
}

